        new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez specializes in algorithm optimization and has industry experience at major tech companies.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 3, CourseCode = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction processing, and an introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Carol Singh", InstructorBio = "Dr. Singh is a database researcher with expertise in distributed systems and query optimization.", DepartmentId = 1, IsFeatured = false },
        new() { Id = 4, CourseCode = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park is an award-winning mathematics educator with a focus on making calculus accessible to all students.", DepartmentId = 2, IsFeatured = true },
        new() { Id = 5, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues and eigenvectors, and applications to data science.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Eva Novak", InstructorBio = "Dr. Novak researches applications of linear algebra in machine learning and computational biology.", DepartmentId = 2, IsFeatured = false },
        new() { Id = 6, CourseCode = "MATH 301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, regression analysis, and Bayesian inference.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park is an award-winning mathematics educator with a focus on making calculus accessible to all students.", DepartmentId = 2, IsFeatured = false },
        new() { Id = 7, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM + Fri Lab 2:00–4:50 PM", InstructorName = "Dr. Frank Wilson", InstructorBio = "Dr. Wilson is an experimental physicist whose research focuses on quantum optics.", DepartmentId = 3, IsFeatured = true },
        new() { Id = 8, CourseCode = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Continuation of General Physics I with laboratory component.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM + Fri Lab 10:00–12:50 PM", InstructorName = "Dr. Grace Lee", InstructorBio = "Dr. Lee specializes in condensed matter physics and enjoys bridging theory and experiment in the classroom.", DepartmentId = 3, IsFeatured = false },
        new() { Id = 9, CourseCode = "ENG 101", Title = "English Composition", Description = "Develops critical reading, thinking, and writing skills. Students produce essays in multiple genres and learn revision strategies.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Prof. Hannah Brooks", InstructorBio = "Prof. Brooks is a published author and writing coach with expertise in rhetoric and composition studies.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 10, CourseCode = "ENG 220", Title = "American Literature", Description = "Survey of American literary traditions from the colonial period to the present, including poetry, fiction, and nonfiction.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", InstructorName = "Dr. Ian Torres", InstructorBio = "Dr. Torres is a scholar of 20th-century American fiction with a particular interest in multicultural narratives.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 11, CourseCode = "HIST 101", Title = "World History to 1500", Description = "A survey of human civilizations from prehistory through the late medieval period, covering political, economic, and cultural developments.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", InstructorName = "Dr. Julia Hammond", InstructorBio = "Dr. Hammond is a medieval historian specializing in cross-cultural exchange along ancient trade routes.", DepartmentId = 5, IsFeatured = false },
        new() { Id = 12, CourseCode = "HIST 202", Title = "Modern World History", Description = "Global developments from 1500 to the present including colonialism, industrialization, world wars, and globalization.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Kevin Okafor", InstructorBio = "Dr. Okafor researches modern African history and the lasting impacts of colonialism on contemporary societies.", DepartmentId = 5, IsFeatured = true },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetAllCourses() => _courses;
}

